#!/usr/bin/env bun
/**
 * eval-judikatur-pending-batch — honest baseline for the 36 draft judikatur
 * questions in server/test/fixtures/retrieval-quality/legal-at-judikatur/
 * pending-review.ts (generated by draft-judikatur-gold-questions.ts).
 *
 *   bun run server/scripts/eval-judikatur-pending-batch.ts
 *
 * Seeds a fresh PGLiteEngine with the 20 reviewed gold decisions + the 36
 * draft decisions + DE statute distractors, runs runRetrievalQuality +
 * jurisdiction purity, and writes METRICS.md. No API key — keyword-only
 * hybrid search (same as the reviewed gold-set gate).
 */

import { readFileSync, writeFileSync } from "fs";
import { join } from "path";
import { PGLiteEngine } from "../src/core/pglite-engine.ts";
import { hybridSearch } from "../src/core/search/hybrid.ts";
import {
  runRetrievalQuality,
  type SearchFn,
  type NamedThingQuestion,
} from "../src/eval/retrieval-quality/harness.ts";
import type { ChunkInput } from "../src/core/types.ts";

const REPO = join(import.meta.dir, "..", "..");
const JUDIKATUR_DIR = join(REPO, "server", "law-corpus", "at-judikatur");
const METRICS_FILE = join(
  REPO,
  "server",
  "test",
  "fixtures",
  "retrieval-quality",
  "legal-at-judikatur",
  "METRICS.md"
);

const { seedJudikaturCorpus, seedDeDistractors, JUDIKATUR_GOLD } =
  await import("../test/fixtures/retrieval-quality/legal-at-judikatur/corpus.ts");
const { JUDIKATUR_PENDING } =
  await import("../test/fixtures/retrieval-quality/legal-at-judikatur/pending-review.ts");

const slugOfDraft = (fileBase: string) => `legal/judikatur/at/${fileBase}`;

async function seedDrafts(engine: PGLiteEngine): Promise<void> {
  const sourceId = "law-at-judikatur";
  for (const d of JUDIKATUR_PENDING) {
    const path = join(JUDIKATUR_DIR, `${d.fileBase}.md`);
    let body: string;
    try {
      body = readFileSync(path, "utf8");
    } catch {
      throw new Error(
        `judikatur draft drift: ${d.fileBase}.md not found — fix the draft or the corpus.`
      );
    }
    const slug = slugOfDraft(d.fileBase);
    await engine.putPage(
      slug,
      {
        type: "court_decision" as never,
        title: `OGH — ${d.caseNumber}`,
        compiled_truth: body,
        timeline: "",
        frontmatter: {
          jurisdiction: "at",
          court: "OGH",
          case_number: d.caseNumber,
          legal_area: d.legalArea,
        },
      },
      { sourceId }
    );
    await engine.upsertChunks(
      slug,
      [
        {
          chunk_index: 0,
          chunk_text: body,
          chunk_source: "compiled_truth",
          token_count: body.split(/\s+/).length,
        },
      ] satisfies ChunkInput[],
      { sourceId }
    );
  }
}

function toQuestions(): NamedThingQuestion[] {
  return JUDIKATUR_PENDING.map((d) => ({
    family: "keyword" as const,
    query: d.query,
    relevant: [slugOfDraft(d.fileBase)],
  }));
}

async function measurePurity(engine: PGLiteEngine): Promise<{ leaks: string[]; total: number }> {
  const leaks: string[] = [];
  for (const d of JUDIKATUR_PENDING) {
    const results = await hybridSearch(engine, d.query, {
      limit: 10,
      expansion: false,
      jurisdiction: "at",
    });
    const foreign = results.map((r) => r.slug).filter((s) => s.startsWith("legal/statutes/de/"));
    if (foreign.length > 0) leaks.push(`[${d.normAbbr}] "${d.query}" → ${foreign.join(", ")}`);
  }
  return { leaks, total: JUDIKATUR_PENDING.length };
}

console.log(
  `Seeding + evaluating ${JUDIKATUR_PENDING.length} draft judikatur questions (jurisdiction=at)...\n`
);

const eng = new PGLiteEngine();
await eng.connect({});
await eng.initSchema();
await seedJudikaturCorpus(eng); // 20 reviewed gold decisions (existing gate)
await seedDrafts(eng); // 36 new draft decisions
await seedDeDistractors(eng); // purity distractors

const searchFn: SearchFn = async (q) => {
  const results = await hybridSearch(eng, q, { limit: 10, expansion: false, jurisdiction: "at" });
  return results.map((r) => r.slug);
};

const questions = toQuestions();
const report = await runRetrievalQuality(questions, searchFn);
const n = report.questions.length || 1;
const hit1 = report.questions.filter((r) => r.hit_at_1).length / n;
const hit3 = report.questions.filter((r) => r.hit_at_3).length / n;
const mrr = report.questions.reduce((s, r) => s + r.reciprocal_rank, 0) / n;
const recall3 = report.questions.reduce((s, r) => s + r.recall_at_k, 0) / n;

// Per-statute breakdown
const byAbbr = new Map<string, { n: number; hit1: number; hit3: number; mrr: number }>();
for (let i = 0; i < JUDIKATUR_PENDING.length; i++) {
  const abbr = JUDIKATUR_PENDING[i].normAbbr;
  const r = report.questions[i];
  const cur = byAbbr.get(abbr) ?? { n: 0, hit1: 0, hit3: 0, mrr: 0 };
  cur.n++;
  if (r.hit_at_1) cur.hit1++;
  if (r.hit_at_3) cur.hit3++;
  cur.mrr += r.reciprocal_rank;
  byAbbr.set(abbr, cur);
}

const { leaks, total: purityTotal } = await measurePurity(eng);
await eng.disconnect();

console.log(
  `OVERALL (n=${n}): hit@1=${(hit1 * 100).toFixed(1)}% hit@3=${(hit3 * 100).toFixed(1)}% MRR=${mrr.toFixed(3)} recall@3=${(recall3 * 100).toFixed(1)}%`
);
console.log(`Purity: ${purityTotal - leaks.length}/${purityTotal} (${leaks.length} leaks)`);
for (const [abbr, s] of byAbbr) {
  console.log(
    `  ${abbr}: n=${s.n} hit@1=${((s.hit1 / s.n) * 100).toFixed(1)}% hit@3=${((s.hit3 / s.n) * 100).toFixed(1)}% MRR=${(s.mrr / s.n).toFixed(3)}`
  );
}

const lines: string[] = [
  "# AT Judikatur Retrieval — Draft Question Metrics",
  "",
  `Generated: ${new Date().toISOString()}`,
  `Draft questions: ${JUDIKATUR_PENDING.length} (plus ${JUDIKATUR_GOLD.length} reviewed gold, seeded together)`,
  "",
  "> Leakage-free (2026-07-14): no query contains the target decision's Geschäftszahl.",
  "> Draft queries are auto-extracted Rechtssatz keywords — read as word-salad, not yet",
  "> reviewed. SMALL-HAYSTACK CAVEAT: only these 56 decisions + 3 DE distractors are",
  "> seeded — hit@1=100% here does NOT transfer to the real ~10,807-decision corpus,",
  "> it only proves purity + structural correctness. A honest baseline against the full",
  "> corpus requires seeding (or querying) the production DB, not a fresh PGLite engine.",
  "",
  "## Overall (jurisdiction=at, keyword-only hybrid search)",
  "",
  `| Metric | Score |`,
  `|---|---|`,
  `| hit@1 | ${(hit1 * 100).toFixed(1)}% |`,
  `| hit@3 | ${(hit3 * 100).toFixed(1)}% |`,
  `| MRR | ${mrr.toFixed(3)} |`,
  `| recall@3 | ${(recall3 * 100).toFixed(1)}% |`,
  `| Purity | ${(((purityTotal - leaks.length) / purityTotal) * 100).toFixed(1)}% (${leaks.length} leaks) |`,
  "",
  "## Per-Statute Breakdown",
  "",
  "| Norm | n | hit@1 | hit@3 | MRR |",
  "|---|---|---|---|---|",
  ...[...byAbbr.entries()].map(
    ([abbr, s]) =>
      `| ${abbr} | ${s.n} | ${((s.hit1 / s.n) * 100).toFixed(1)}% | ${((s.hit3 / s.n) * 100).toFixed(1)}% | ${(s.mrr / s.n).toFixed(3)} |`
  ),
];
if (leaks.length > 0) {
  lines.push("", "## Leaks", "", ...leaks.map((l) => `- ${l}`));
}
writeFileSync(METRICS_FILE, lines.join("\n"), "utf8");
console.log(`\nWritten: ${METRICS_FILE}`);
